; Title module: title screen, name entry, ROM text/inventory patches and
; Goku's arrival at the Mana Sword.
;   code  !CODE_MISC ($AB:8000-FFFF, ROM 0x2B8000)
;   data  !DATA_MISC ($EB:0000-7FFF, ROM 0x2B0000), mostly generated by
;         snes/gen/title.mjs into dist/snes/gen/title/title.asm
;   WRAM  !RAM_MISC  ($7E:DD80, $80 bytes)
;   SRAM  !PERSIST_MISC ($31:6300, $100 bytes) and !persist_goku_active
; See docs/agents/snes-port/title.md.

; ---------------------------------------------------------------------------
; WRAM (!RAM_MISC, $80 bytes; cleared by core at every title entry)
!title_flags        = !RAM_MISC+$00   ; byte: bit0 name prefilled since the last title entry
!title_tmp          = !RAM_MISC+$02   ; word scratch (main thread only)
!title_tmp2         = !RAM_MISC+$04   ; word scratch (main thread only)
!title_phase        = !RAM_MISC+$06   ; byte: arrival phase (!TITLE_PH_*)
!title_sfx          = !RAM_MISC+$07   ; byte: 1 descent began, 2 impact began (for audio; consumer clears)
!title_ticks        = !RAM_MISC+$08   ; word: field frames in the current arrival phase
!title_hero_mode    = !RAM_MISC+$0A   ; byte: 0 native hero, 1 hidden (Goku in the pod), 2 hop sprite
!title_hero_frame   = !RAM_MISC+$0B   ; byte: Goku sheet column for the hop sprite (37 air, 36 landed), row 0
!title_hero_x       = !RAM_MISC+$0C   ; word: hop sprite screen x (32x32 top-left)
!title_hero_y       = !RAM_MISC+$0E   ; word: hop sprite screen y
!title_pod_ready    = !RAM_MISC+$10   ; byte: pod frame (0-3) in OBJ VRAM, $FF none
!title_pod_queued   = !RAM_MISC+$11   ; byte: pod frame queued this frame, $FF none
!title_vram_ready   = !RAM_MISC+$12   ; byte: bit0 crater, bit1 fx1, bit2 fx2 cells in VRAM
!title_vram_queued  = !RAM_MISC+$13   ; byte: same bits, queued this frame
!title_scr_x        = !RAM_MISC+$14   ; word: sword (crater centre) screen x this frame
!title_scr_y        = !RAM_MISC+$16   ; word: sword screen y
!title_last_tick    = !RAM_MISC+$18   ; word: !core_tick of the last field frame seen
!title_claims       = !RAM_MISC+$1D   ; byte: bit0 pool A, bit1 pool B held, bit7 claim refused
!title_status       = !RAM_MISC+$1E   ; byte: bit1 title program patched (diagnostic)
; +$20-$27 names.asm (crown buffer)
!title_last_map     = !RAM_MISC+$28   ; word: map of the last field frame
!title_age          = !RAM_MISC+$2A   ; word: animation age being drawn
!title_tmp3         = !RAM_MISC+$2C   ; word scratch
!title_tmp4         = !RAM_MISC+$2E   ; word scratch
!title_oam_cur      = !RAM_MISC+$30   ; word: OAM byte offset of the next module sprite
!title_oam_end      = !RAM_MISC+$32   ; word: first OAM byte offset we may not use
!title_oam_first    = !RAM_MISC+$34   ; word: OAM byte offset of our first sprite this frame
!title_negx_n       = !RAM_MISC+$36   ; word: sprites with negative x this frame (high bit)
!title_negx         = !RAM_MISC+$38   ; 8 bytes: their slots
!title_tint         = !RAM_MISC+$40   ; word: crater tint in 7E:0600 (r | g | b offsets in place)
!title_hero_col     = !RAM_MISC+$42   ; byte: sheet column of the cached hop cell, 0 none
!title_hero_cell    = !RAM_MISC+$44   ; word: cached !goku_cell_req value for that column
!title_count        = !RAM_MISC+$46   ; word: loop counter
!title_ox           = !RAM_MISC+$48   ; word: sprite list origin x
!title_oy           = !RAM_MISC+$4A   ; word: sprite list origin y
!title_map_x        = !RAM_MISC+$4C   ; word: sword screen x on BG1's scroll (crater, resting pod)
!title_map_y        = !RAM_MISC+$4E   ; word: sword screen y on BG1's scroll
; +$50-$5F free
!title_palstate     = !RAM_MISC+$60   ; byte: bit0 our OBJ palettes are in 7E:0600
!title_palfx        = !RAM_MISC+$62   ; word: effect palette variant last written

!TITLE_PH_PROLOGUE = 0
!TITLE_PH_QUEUED   = 1
!TITLE_PH_DESCENT  = 2
!TITLE_PH_IMPACT   = 3
!TITLE_PH_GHOST    = 4
!TITLE_PH_DIALOGUE = 5
!TITLE_PH_COMPLETE = 6

; Persistent (SRAM !PERSIST_MISC): survives saves through the core sidecars.
!persist_title_arrival = !PERSIST_MISC+$00 ; byte: bit0 Goku arrived, bit1 crater/pod scenery on map 128

pushpc
org !DATA_MISC
title_data_start:
incsrc "title/title.asm"
incsrc "title/arrival-data.asm"
incsrc "data.asm"
title_data_end:
assert title_data_end <= !DATA_MISC+$8000, "title data bank overflow"

org !CODE_MISC
title_code_start:
incsrc "boot.asm"
incsrc "names.asm"
incsrc "patches.asm"
incsrc "arrival.asm"
incsrc "title/arrival-code.asm"
title_code_end:
assert title_code_end <= !CODE_MISC+$8000, "title code bank overflow"
pullpc

incsrc "hooks.asm"
